// Açık sinyallerin hedefe/stopa ulaşıp ulaşmadığını kontrol eder.
const API = 'https://kripto-sinyal.erenkaraca2005.workers.dev';
const KEY = 'BURAYA_API_ANAHTARI';
const h = this.helpers;
const list = await h.httpRequest({ url: API + '/api/signals', json: true });
const out = [];
for (const s of list.filter(x => x.status === 'open')) {
  const k = await h.httpRequest({ url: `https://api.binance.com/api/v3/klines?symbol=${s.symbol}&interval=5m&startTime=${new Date(s.time).getTime()}&limit=1000`, json: true });
  let res = null;
  for (const c of k) {
    const hi = +c[2], lo = +c[3], buy = s.side === 'BUY';
    const hitSl = buy ? lo <= s.sl : hi >= s.sl;
    const hitTp = buy ? hi >= s.tp : lo <= s.tp;
    if (hitSl) { res = 'sl'; break; }
    if (hitTp) { res = 'tp'; break; }
  }
  if (res) {
    await h.httpRequest({ method: 'PATCH', url: `${API}/api/signals/${s.id}`, headers: { Authorization: 'Bearer ' + KEY }, body: { status: res }, json: true });
    out.push({ json: { id: s.id, symbol: s.symbol, sonuc: res } });
  }
}
return out;
